// No campaign IDs. Inspect EVERY EspoCRM Campaign using the installed native node.
const records=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
const seen=new Set(),campaigns=[];
for(const c of records){
  if(typeof c.id!=='string'||!c.id||seen.has(c.id))throw new Error('Invalid or duplicate EspoCRM Campaign record');
  seen.add(c.id);
  // Restrict result to non-sensitive campaign operational fields.
  campaigns.push({id:c.id,name:typeof c.name==='string'?c.name:null,status:c.status||null,
    trackingEnabled:c.ageTrackingEnabled===true,provider:c.ageProvider||null,
    inboxId:c.ageInboxId??null,templateName:c.ageTemplateName||null});
}
return [{json:{espoReadable:true,espoCampaignCount:campaigns.length,activeCount:campaigns.filter(c=>c.status==='Active').length,
  whatsappCandidateCount:campaigns.filter(c=>c.provider&&String(c.provider).includes('Chatwoot')).length,
  // Existing EspoCRM campaign metadata is not proof of a Chatwoot one-off batch.
  espoCampaigns:campaigns}}];

// Discover and summarize independently. Never join by title/name or assume CRM ID equals Chatwoot ID.
const crm=$('Summarize CRM Inventory').first().json;
const raw=$input.all().map(x=>x.json).filter(x=>x&&Object.keys(x).length);
const seen=new Set(),list=[];
for(const c of raw){
  const id=Number(c.id);
  if(!Number.isSafeInteger(id)||id<=0||seen.has(id))throw new Error('Invalid or duplicate Chatwoot campaign');
  seen.add(id);
  list.push({id,title:typeof c.title==='string'?c.title.slice(0,100):null,
    type:c.campaign_type||null,status:c.campaign_status||null,
    inboxType:c.inbox?.channel_type||null,inboxId:c.inbox?.id??null});
}
const whatsapp=list.filter(c=>c.type==='one_off'&&c.inboxType==='Channel::Whatsapp');
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',campaignIdsRequired:false,
    espoCampaignCount:crm.espoCampaignCount,espoActiveCount:crm.activeCount,
    chatwootCampaignCount:list.length,chatwootNativeWhatsAppCount:whatsapp.length,
    chatwootWhatsAppCampaigns:whatsapp,
    espocrmCampaigns:crm.espoCampaigns,
    crossSystemCampaignMappingVerified:false,
    customAGECampaignSummaryTested:false,campaignAnalyticsTested:false,
    note:'CRM Campaign IDs and Chatwoot native campaign display IDs are distinct; only a recorded batch ledger can safely join them.',
    canDispatch:false,crmEventWriteAuthorized:false,liveSendAttempted:false}}];
